    w = unpack_interpolate(kernel, vec2(0.75 + (x / 4), index));
    w = w * kernel_scale + kernel_bias;
    r += c0 * w;
    w = unpack_interpolate(kernel, vec2(0.25 - (x / 4), index));
    w = w * kernel_scale + kernel_bias;
    r += c4 * w;
    w = unpack_interpolate(kernel, vec2(0.5 + (x / 4), index));
    w = w * kernel_scale + kernel_bias;
    r += c1 * w;
    w = unpack_interpolate(kernel, vec2(0.5 - (x / 4), index));
    w = w * kernel_scale + kernel_bias;
    r += c5 * w;
