    w = w * kernel_scale + kernel_bias;
    r += c2 * w;
    w = unpack_interpolate(kernel, vec2(0.75 - (x / 4), index));
    w = w * kernel_scale + kernel_bias;
    r += c6 * w;
    w = unpack_interpolate(kernel, vec2(0.0 + (x / 4), index));
    w = w * kernel_scale + kernel_bias;
    r += c3 * w;
    w = unpack_interpolate(kernel, vec2(1.0 - (x / 4), index));
    w = w * kernel_scale + kernel_bias;
    r += c7 * w;
    return r;
}

